import{_ as a,o as s,c as e,e as n}from"./app-6be1f847.js";const i={},r=n(`<h1 id="ipv4-流量转发-a机器请求转发到b机器-b代理上网" tabindex="-1"><a class="header-anchor" href="#ipv4-流量转发-a机器请求转发到b机器-b代理上网" aria-hidden="true">#</a> IPv4 流量转发：A机器请求转发到B机器，B代理上网</h1><h2 id="架构" tabindex="-1"><a class="header-anchor" href="#架构" aria-hidden="true">#</a> 架构</h2><p><strong>A机器</strong>：内网客户端，所有流量走B机器 <strong>B机器</strong>：中转网关，开启IP转发+SNAT，代A上网 全流程纯IPv4，Linux环境通用</p><hr><h2 id="一、b机器配置-中转服务器" tabindex="-1"><a class="header-anchor" href="#一、b机器配置-中转服务器" aria-hidden="true">#</a> 一、B机器配置（中转服务器）</h2><h3 id="_1-开启内核ipv4转发" tabindex="-1"><a class="header-anchor" href="#_1-开启内核ipv4转发" aria-hidden="true">#</a> 1. 开启内核IPv4转发</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 临时生效</span>
<span class="token builtin class-name">echo</span> <span class="token number">1</span> <span class="token operator">&gt;</span> /proc/sys/net/ipv4/ip_forward

<span class="token comment"># 永久生效</span>
<span class="token function">sed</span> <span class="token parameter variable">-i</span> <span class="token string">&#39;s/^net.ipv4.ip_forward=0/net.ipv4.ip_forward=1/&#39;</span> /etc/sysctl.conf
<span class="token function">sysctl</span> <span class="token parameter variable">-p</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-配置iptables-snat-流量转发" tabindex="-1"><a class="header-anchor" href="#_2-配置iptables-snat-流量转发" aria-hidden="true">#</a> 2. 配置iptables SNAT 流量转发</h3><p>假设：</p><ul><li>B机器<strong>外网网卡</strong>：<code>eth0</code></li><li>B机器<strong>内网网卡/对接A网段</strong>：<code>eth1</code></li><li>A机器网段：<code>192.168.1.0/24</code></li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 清空旧转发规则</span>
iptables <span class="token parameter variable">-F</span>
iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-F</span>

<span class="token comment"># 所有从内网 192.168.1.0/24 过来、从外网网卡 eth0 发出去的流量，统一伪装成 B 机器外网 IP 上网。</span>
iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> POSTROUTING <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.0/24 <span class="token parameter variable">-j</span> MASQUERADE

<span class="token comment"># 放行转发流量</span>
<span class="token comment">#允许内网 A 机器发来的流量，经过 B 机器转发出去。</span>
iptables <span class="token parameter variable">-A</span> FORWARD <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.0/24 <span class="token parameter variable">-j</span> ACCEPT

<span class="token comment">#允许外网返回的响应流量，转发回内网 A 机器。</span>
iptables <span class="token parameter variable">-A</span> FORWARD <span class="token parameter variable">-d</span> <span class="token number">192.168</span>.1.0/24 <span class="token parameter variable">-j</span> ACCEPT
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-保存iptables规则-防止重启失效" tabindex="-1"><a class="header-anchor" href="#_3-保存iptables规则-防止重启失效" aria-hidden="true">#</a> 3. 保存iptables规则（防止重启失效）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># CentOS</span>
yum <span class="token function">install</span> <span class="token parameter variable">-y</span> iptables-services
<span class="token function">service</span> iptables save

<span class="token comment"># Debian/Ubuntu</span>
iptables-save <span class="token operator">&gt;</span> /etc/iptables/rules.v4
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、a机器配置-客户端全部流量走b" tabindex="-1"><a class="header-anchor" href="#二、a机器配置-客户端全部流量走b" aria-hidden="true">#</a> 二、A机器配置（客户端全部流量走B）</h2><h3 id="_1-设置默认网关为b机器内网ip" tabindex="-1"><a class="header-anchor" href="#_1-设置默认网关为b机器内网ip" aria-hidden="true">#</a> 1. 设置默认网关为B机器内网IP</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 示例：B机器内网IP=192.168.1.100</span>
route <span class="token function">add</span> default gw <span class="token number">192.168</span>.1.100

<span class="token comment"># 永久配置（改网卡配置）</span>
<span class="token comment"># /etc/sysconfig/network-scripts/ifcfg-xxx</span>
<span class="token assign-left variable">GATEWAY</span><span class="token operator">=</span><span class="token number">192.168</span>.1.100
<span class="token assign-left variable">DNS1</span><span class="token operator">=</span><span class="token number">223.5</span>.5.5
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-仅转发指定端口-精准转发-非全量流量" tabindex="-1"><a class="header-anchor" href="#_2-仅转发指定端口-精准转发-非全量流量" aria-hidden="true">#</a> 2. 仅转发指定端口（精准转发，非全量流量）</h3><p>若<strong>不全局代理</strong>，只把A特定端口请求转发到B再出站：</p><h4 id="a机器-端口转发到b" tabindex="-1"><a class="header-anchor" href="#a机器-端口转发到b" aria-hidden="true">#</a> A机器：端口转发到B</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># A本地8080端口 转发到 B机器 8080</span>
iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> OUTPUT <span class="token parameter variable">-p</span> tcp <span class="token parameter variable">--dport</span> <span class="token number">8080</span> <span class="token parameter variable">-j</span> DNAT --to-destination <span class="token number">192.168</span>.1.100:8080
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="b机器-接收后转发外网" tabindex="-1"><a class="header-anchor" href="#b机器-接收后转发外网" aria-hidden="true">#</a> B机器：接收后转发外网</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-A</span> PREROUTING <span class="token parameter variable">-p</span> tcp <span class="token parameter variable">--dport</span> <span class="token number">8080</span> <span class="token parameter variable">-j</span> REDIRECT --to-ports <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><hr><h2 id="三、windows-a机器-配置-非linux客户端" tabindex="-1"><a class="header-anchor" href="#三、windows-a机器-配置-非linux客户端" aria-hidden="true">#</a> 三、Windows A机器 配置（非Linux客户端）</h2><ol><li>网卡IPv4属性</li><li><strong>默认网关</strong>填写：B机器内网IP</li><li>DNS服务器填写公共DNS</li><li>确定后，所有网络请求自动走B中转上网</li></ol><hr><h2 id="四、验证连通性" tabindex="-1"><a class="header-anchor" href="#四、验证连通性" aria-hidden="true">#</a> 四、验证连通性</h2><p>A机器执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">traceroute</span> <span class="token number">223.5</span>.5.5
<span class="token function">curl</span> cip.cc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>看到出口IP为<strong>B机器公网IP</strong>即转发成功</p><hr><h2 id="五、关闭转发" tabindex="-1"><a class="header-anchor" href="#五、关闭转发" aria-hidden="true">#</a> 五、关闭转发</h2><h3 id="b机器" tabindex="-1"><a class="header-anchor" href="#b机器" aria-hidden="true">#</a> B机器</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">echo</span> <span class="token number">0</span> <span class="token operator">&gt;</span> /proc/sys/net/ipv4/ip_forward
iptables <span class="token parameter variable">-t</span> nat <span class="token parameter variable">-D</span> POSTROUTING <span class="token parameter variable">-o</span> eth0 <span class="token parameter variable">-s</span> <span class="token number">192.168</span>.1.0/24 <span class="token parameter variable">-j</span> MASQUERADE
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div>`,35),l=[r];function t(p,d){return s(),e("div",null,l)}const o=a(i,[["render",t],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/others/computerNetwork/ipv4_forwarding.html.vue"]]);export{o as default};
